export class StatusNotice{
 constructor({t,documentRef=document}={}){this.t=t;this.document=documentRef;this.dialog=documentRef.createElement('dialog');this.dialog.className='stall-status-dialog';this.dialog.id='stall-status-dialog';this.dialog.setAttribute('aria-labelledby','stall-status-title');this.dialog.setAttribute('aria-describedby','stall-status-message');this.dialog.innerHTML='<button type="button" class="status-notice-close" data-notice-close>×</button><span class="status-notice-symbol" aria-hidden="true">!</span><p class="status-notice-stall"></p><h2 id="stall-status-title"></h2><p id="stall-status-message"></p><button type="button" class="button status-notice-action"></button>';documentRef.body.append(this.dialog);this.dialog.querySelector('[data-notice-close]').addEventListener('click',()=>this.close());this.dialog.querySelector('.status-notice-action').addEventListener('click',()=>{const retry=this.retry;this.close();retry?.();});this.dialog.addEventListener('click',event=>{if(event.target===this.dialog){const rect=this.dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)this.close();}});this.dialog.addEventListener('close',()=>{this.retry=null;const previous=this.previousFocus;this.previousFocus=null;const usable=previous?.isConnected&&previous!==this.document.body,detail=this.kind==='reserved'?(this.document.querySelector('#stall-detail .enquire-stall')||this.document.querySelector('#stall-directory [aria-pressed="true"]')):null,target=usable?previous:detail||this.document.querySelector('#stall-search');target?.focus?.({preventScroll:true});});}
 get open(){return this.dialog.open;}
 show(kind,{stall=null,retry=null,returnFocus=null}={}){this.kind=kind;this.stall=stall;this.retry=retry;if(!this.dialog.open)this.previousFocus=returnFocus??this.document.activeElement;this.localize();if(!this.dialog.open)this.dialog.showModal();this.dialog.querySelector('.status-notice-action').focus({preventScroll:true});}
 localize(){if(!this.kind)return;const t=this.t,keys=this.kind==='sold_out'?['bookingSoldOut','bookingSoldOutWarning']:this.kind==='reserved'?['bookingReserved','bookingReservedWarning']:['bookingUnknownTitle','bookingUnknownWarning'];this.dialog.dataset.status=this.kind;this.dialog.querySelector('#stall-status-title').textContent=t(keys[0]);this.dialog.querySelector('#stall-status-message').textContent=t(keys[1]);this.dialog.querySelector('.status-notice-stall').textContent=this.stall?`${t('stall')} ${this.stall}`:'';this.dialog.querySelector('[data-notice-close]').setAttribute('aria-label',t('close'));this.dialog.querySelector('.status-notice-action').textContent=t(this.kind==='unknown'&&this.retry?'bookingRetry':this.kind==='sold_out'?'bookingChooseAnother':'bookingContinue');}
 close(){if(this.dialog.open)this.dialog.close();}
}
